DOMAIN.nodeActs=n=>{const id=n.id,t=n.type;let a="";
  if(t==="CloudLab::Client"&&refId(n.props.Target))a+=`<button class="sm" data-act="inject" data-arg="${id}">Gửi 1 request</button>`;
  if(t==="CloudLab::Uploader"&&refId(n.props.Target))a+=`<button class="sm" data-act="inject" data-arg="${id}">Upload 1 file</button>`;
  if(t==="AWS::SNS::Topic"&&exists(id))a+=`<button class="sm" data-act="pubTest" data-arg="${id}">Gửi tin thử</button>`;
  if(t==="AWS::S3::Bucket"&&exists(id)&&Object.keys(RT.obj[id]||{}).length)a+=`<button class="sm" data-act="askEmpty" data-arg="${id}">Empty</button>`;
  if(typeof orgActs==="function")a+=orgActs(n);
  return a};
DOMAIN.beforeDelete=n=>{const arg=n.id;if(n.type==="AWS::S3::Bucket"&&n.scope==="manual"&&Object.keys(RT.obj[arg]||{}).length){log("API","s3","DeleteBucket","BucketNotEmpty: The bucket you tried to delete is not empty.","bad",`aws s3 rb s3://${physName(n)}`);gNote(`BucketNotEmpty: ${arg} còn object nên chưa xóa được. Bấm Empty trong khung chi tiết, rồi xóa lại.`,"warn");return false}return true};
DOMAIN.afterDelete=n=>{if(n.scope==="manual"){log("API","s3","DeleteBucket",physName(n),"warn",`aws s3 rb s3://${physName(n)}`);delete RT.obj[n.id];delete RT.n[n.id]}};
/* the IAM policy simulator inside a role's runtime panel */
DOMAIN.onChange=t=>{if(t.id==="iq-a"||t.id==="iq-r"){UI.iamq={a:document.getElementById("iq-a").value,r:document.getElementById("iq-r").value};refreshRt();return true}};
/* data-act handlers: (arg, element) → true keeps the page as is */
Object.assign(DOMAIN.actions,{
  askDelete(arg,t){const sb=UI.mode==="sandbox";UI.modal={title:`Xóa stack ${M.name}?`,submitLabel:"Xóa stack",cancel:"Giữ stack",danger:true,init:{wipe:0},
      body:`<p>CloudFormation sẽ xóa ${RT.stack.status==="DELETE_FAILED"?(RT.stack.left||[]).length:Object.keys(M.res).length} tài nguyên của stack và ngừng tính tiền cho chúng. Tài nguyên có <code>DeletionPolicy: Retain</code> được giữ lại và vẫn tính tiền.</p><p>Template giữ nguyên: các khối ở lại trên canvas với trạng thái “Đã xóa”, bấm Deploy để tạo lại lúc nào cũng được.</p><p class="note"><code>aws cloudformation delete-stack --stack-name ${esc(M.name)}</code></p>`,
      fields:sb?[{type:"checks",label:"Canvas",items:[["wipe","Xóa luôn các khối khỏi canvas (template trống)"]]}]:[],
      submit:v=>{simPlay(false);deleteStack();if(sb&&+v.wipe&&RT.stack.status==="DELETE_COMPLETE"){edit("xóa canvas",()=>{M.res={};M.ext={}});RT.stack.status="NOT_DEPLOYED";log("CloudLab","editor","clear","Template trống · tài nguyên tạo tay và bucket Retain vẫn còn","ok")}return{ok:true}}}},
  orgAct(arg,t){const k=arg.indexOf(":");ORG_ACTS[arg.slice(0,k)](arg.slice(k+1))},
  askEmpty(arg,t){const n=nodeOf(arg);confirmModal(`Empty bucket ${arg}?`,`Toàn bộ ${num(Object.values(RT.obj[arg]||{}).reduce((a,x)=>a+x.n,0))} object trong ${esc(physName(n))} sẽ bị xóa vĩnh viễn.`,"Empty bucket",()=>{RT.obj[arg]={};log("API","s3","DeleteObjects",`${physName(n)}: làm rỗng`,"warn",`aws s3 rm s3://${physName(n)} --recursive`);UI.dirty=true},true)},
  cleanJunk(arg,t){const st=RT.obj[arg]||{},ks=Object.keys(st).filter(k=>k.startsWith("incoming/")&&k.endsWith(".json"));ks.forEach(k=>delete st[k]);log("API","s3","DeleteObjects",`${ks.length} file .json trong incoming/`,"warn",`aws s3 rm s3://${physName(nodeOf(arg))}/incoming/ --recursive --exclude "*" --include "*.json"`);UI.dirty=true},
  inject(arg,t){const n=nodeOf(arg);if(!stackUp()&&Object.keys(M.res).length&&RT.stack.status==="NOT_DEPLOYED")deploy();inject(n,1);log("Thử","sim",n.type==="CloudLab::Uploader"?"upload":"request",`${arg}: 1 ${n.type==="CloudLab::Uploader"?"file":"request"}`,"")},
  pubTest(arg,t){push({at:RT.t,to:arg,w:1,type:"pub",data:{subject:"Tin thử từ CloudLab",body:"Bạn đọc được thư này nghĩa là subscription đang hoạt động."}});drain();log("Thử","sns","Publish",`tin thử tới ${arg}`,"",`aws sns publish --topic-arn ${arnOf(arg)} --message "test"`)},
  openMail(arg,t){UI.mailOpen=arg;for(const L of Object.values(RT.inbox)){const m=L.find(x=>x.id===arg);if(m)m.read=true}},
  confirmMail(arg,t){for(const[ib,L]of Object.entries(RT.inbox)){const m=L.find(x=>x.id===arg);if(m&&m.topic){if(confirmSub(m.topic,(nodeOf(ib).props||{}).Address))m.done=true}}UI.dirty=true},
  envAdd(arg,t){edit("env",()=>{const n=nodeOf(arg);const v=getP(n.props,"Environment.Variables")||{};v["VAR_"+(Object.keys(v).length+1)]="";setP(n.props,"Environment",{Variables:v})})},
  rowAdd(arg,t){const fs=t.closest("[data-ftype]"),n=nodeOf(fs.dataset.fid),k=fs.dataset.field;edit("thêm dòng",()=>{const cur=arr(getP(n.props,k));setP(n.props,k,cur.concat([arg==="subs"?{Protocol:"email",Endpoint:EMAIL}:arg==="ingress"?{IpProtocol:"tcp",FromPort:80,ToPort:80,CidrIp:"0.0.0.0/0"}:{Event:"s3:ObjectCreated:*",Function:null}]))})},
  polAdd(arg,t){const fs=t.closest("[data-ftype]"),n=nodeOf(fs.dataset.fid);edit("thêm policy",()=>{n.props.Policies=arr(n.props.Policies).concat([{PolicyName:"inline-"+(arr(n.props.Policies).length+1),PolicyDocument:{Version:"2012-10-17",Statement:[{Effect:"Allow",Action:"s3:GetObject",Resource:"*"}]}}])})},
  polDel(arg,t){const fs=t.closest("[data-ftype]");t.closest(".pol").remove();applyField(fs)},
  stmtAdd(arg,t){const fs=t.closest("[data-ftype]"),pol=t.closest(".pol");pol.insertAdjacentHTML("beforeend","");const tmp=document.createElement("div");tmp.innerHTML=stmtRow({Effect:"Allow",Action:"s3:GetObject",Resource:"*"},fs.dataset.ftype==="statements");pol.insertBefore(tmp.firstChild,t);applyField(fs)},
});

/* ---------------- placement: drop EC2 / RDS into a subnet (or a VPC: a subnet is created), accounts into an OU ---------------- */
const PLACEABLE=["AWS::EC2::Instance","AWS::RDS::DBInstance"];
/* EC2/RDS can't sit in a VPC directly — they live in a subnet. Dropped on a VPC area with no subnet: create one there. */
function autoSubnet(id,vpc){let sid;edit(`tạo subnet cho ${id}`,()=>{sid=newSubnetIn(vpc);const p=M.pos[id]||[0,0];M.pos[sid]=[p[0]-20,p[1]-40]});placeIn(id,sid);
  gNote(`${id} cần nằm trong một subnet, nên CloudLab đã tạo ${sid} (${M.res[sid].Properties.CidrBlock}, private) trong ${vpc}. Cần public thì đổi trong khung chi tiết của ${sid}.`,"info")}
function placeIn(id,sid){const n=nodeOf(id);if(!n||!PLACEABLE.includes(n.type))return false;const cur=subnetsOf(n)[0]||null;if(cur===sid)return false;
  edit(sid?`đặt ${id} vào ${sid}`:`đưa ${id} ra khỏi subnet`,()=>{const nn=nodeOf(id);
    if(nn.type==="AWS::EC2::Instance")nn.props.SubnetId=sid?{Ref:sid}:null;
    else{let g=refId(nn.props.DBSubnetGroupName);if(!sid){if(g&&nodeOf(g))nodeOf(g).props.SubnetIds=[];return}if(!g||!nodeOf(g)){g=freeId(id+"Subnets");M.res[g]={Type:"AWS::RDS::DBSubnetGroup",Properties:{DBSubnetGroupDescription:kebab(id)+" subnets",SubnetIds:[]}};nn.props.DBSubnetGroupName={Ref:g}}
      const G=nodeOf(g);G.props.SubnetIds=[{Ref:sid},...arr(G.props.SubnetIds).filter(x=>refId(x)!==sid)].slice(0,3)}});
  log("CloudLab","editor","place",sid?`${id} → subnet ${sid}`:`${id} ra khỏi subnet`,"ok");return true}
/* an internet gateway attached to a VPC is drawn inside the VPC box (AWS diagrams put it on the VPC edge). Dropping it on
   a VPC box attaches it; dragging it out of the box detaches it; attaching it with an arrow moves it into the box. */
const igwAttachments=id=>Object.keys(M.res).filter(k=>M.res[k].Type==="AWS::EC2::VPCGatewayAttachment"&&refId(M.res[k].Properties.InternetGatewayId)===id);
function igwVpc(id){const k=igwAttachments(id)[0];return k?refId(M.res[k].Properties.VpcId):null}
/* keep the gateway clear of the other blocks: inside the VPC box, below what is already there */
function seatIgw(id,vpc){const L=typeof GLAST!=="undefined"&&GLAST;if(!L)return;const box=L.by[vpc],me=L.by[id];if(!box)return;const p=M.pos[id]||[0,0],h=(me&&me.h)||110;
  const inside=p[0]>=box.x&&p[0]+GW<=box.x+box.w&&p[1]>=box.y&&p[1]<=box.y+box.h;
  const hits=L.nodes.some(o=>o.id!==id&&p[0]<o.x+o.w+12&&p[0]+GW>o.x-12&&p[1]<o.y+o.h+12&&p[1]+h>o.y-12)||L.boxes.some(b=>b.id!==vpc&&b.box!=="vpc"&&p[0]<b.x+b.w&&p[0]+GW>b.x&&p[1]<b.y+b.h&&p[1]+h>b.y);
  if(inside&&!hits)return;const pad=(T["AWS::EC2::VPC"].box||{}).pad||24;M.pos[id]=[Math.round(box.x+pad),Math.round(box.y+box.h-pad+18)]}
function attachIgw(id,vpc){const n=nodeOf(id);if(!n||n.type!=="AWS::EC2::InternetGateway"||!vpc)return false;if(igwVpc(id)===vpc){seatIgw(id,vpc);return false}const r=connectRule(id,vpc);if(!r)return false;
  edit(`${id} → ${vpc}`,()=>{for(const k of igwAttachments(id))delete M.res[k];r.apply(true);seatIgw(id,vpc)});log("CloudLab","editor","connect",`${id} → ${vpc}: ${r.label}`,"ok");return true}
function detachIgw(id){const ks=igwAttachments(id);if(!ks.length)return false;const v=igwVpc(id);edit(`tháo ${id} khỏi ${v}`,()=>{for(const k of ks)delete M.res[k]});log("CloudLab","editor","detach",`${id} không còn gắn vào ${v}: public subnet mất đường ra Internet`,"warn");gNote(`${id} đã tháo khỏi ${v}. Kéo lại vào khung VPC để gắn.`,"info");return true}
DOMAIN.onDrop=(id,type,x,y,boxes)=>{if(type==="AWS::EC2::InternetGateway"){const vb=boxAt(boxes,x,y,"vpc");if(vb)attachIgw(id,vb.id);return}const ob=boxAt(boxes,x,y,"ou");if(ob&&type==="AWS::Organizations::Account")moveAcctTo(id,ob.id);const sb=boxAt(boxes,x,y,"subnet"),vb=boxAt(boxes,x,y,"vpc");if(sb)placeIn(id,sb.id);else if(vb&&PLACEABLE.includes(type))autoSubnet(id,vb.id);
  else if(vb&&["AWS::EC2::Subnet","AWS::EC2::SecurityGroup","AWS::ElasticLoadBalancingV2::TargetGroup"].includes(type))edit("vpc",()=>{nodeOf(id).props.VpcId={Ref:vb.id}})};
DOMAIN.dropHint=(type,x,y,boxes)=>{if(type==="AWS::EC2::InternetGateway"){const v=boxAt(boxes,x,y,"vpc");return v?v.id:null}const b=boxAt(boxes,x,y,"subnet")||boxAt(boxes,x,y,"vpc");return b?b.id:null};
DOMAIN.dragHint=(n,c,boxes)=>{let h;if(n.type==="AWS::EC2::InternetGateway"){const v=boxAt(boxes,c[0],c[1],"vpc");return v&&v.id!==igwVpc(n.id)?v.id:null}if(n.type==="AWS::Organizations::Account"){const b=boxAt(boxes,c[0],c[1],"ou");h=b?b.id:null}
  if(PLACEABLE.includes(n.type)){const b=boxAt(boxes.filter(x=>!x.members.includes(n.id)||x.box==="subnet"),c[0],c[1],"subnet");h=b?b.id:null}return h};
DOMAIN.onDragEnd=(n,c,boxes)=>{if(n.type==="AWS::EC2::InternetGateway"){const v=boxAt(boxes,c[0],c[1],"vpc");if(v)attachIgw(n.id,v.id);else detachIgw(n.id);return}if(n.type==="AWS::Organizations::Account"){const ob=boxAt(boxes,c[0],c[1],"ou");if(ob)moveAcctTo(n.id,ob.id)}
  if(PLACEABLE.includes(n.type)){const sb=boxAt(boxes,c[0],c[1],"subnet"),cur=subnetsOf(n)[0]||null;const vb=!sb&&boxAt(boxes,c[0],c[1],"vpc");
    if(sb&&sb.id!==cur)placeIn(n.id,sb.id);else if(vb&&!cur)autoSubnet(n.id,vb.id);else if(!sb&&cur&&!vb)placeIn(n.id,null)}};
/* extra entry points on window.CloudLab (tests, WebMCP, the browser console) */
DOMAIN.api={evalRole:(...a)=>evalRole(...a),evalS3:(...a)=>evalS3(...a),confirmSub:(...a)=>confirmSub(...a),toTerraform:(...a)=>toTerraform(...a),toCdk:(...a)=>toCdk(...a),cfnForAws:(...a)=>cfnForAws(...a)};
/* ---- WebMCP (src/shell/webmcp.js): the AWS-specific tool descriptions, format guide and property paths */
DOMAIN.mcp={guideHref:"learn.html#gemini",artifact:"template",
  d:{get_template:"Lấy template CloudFormation (YAML) của sơ đồ hiện tại, gồm cả Metadata.CloudLab dùng cho mô phỏng.",
    get_format_guide:"Hướng dẫn viết template CloudLab đọc được: loại tài nguyên AWS được hỗ trợ, nguồn tải bên ngoài trong Metadata.CloudLab.External và thuộc tính của chúng. Đọc trước khi gọi load_template.",
    explain_component:"Giải thích một khối hoặc một loại thành phần AWS bằng ngôn ngữ đơn giản (ví dụ ngân hàng) và mô tả kỹ thuật.",
    "explain_component.idOrType":"Id khối trên sơ đồ (ví dụ Db) hoặc loại (ví dụ AWS::RDS::DBInstance)",
    load_template:"Mở một template CloudFormation YAML vào sandbox (thay sơ đồ sandbox hiện tại). Dùng để dựng tình huống của người dùng. Trả về lỗi YAML kèm số dòng, hoặc danh sách khối và vấn đề.",
    "load_template.yaml":"Template CloudFormation YAML; xem get_format_guide",
    "add_component.type":"Loại, ví dụ AWS::S3::Bucket (xem get_format_guide)",
    connect:"Nối khối from tới khối to, giống kéo mũi tên trên canvas (ví dụ Lambda → bucket thêm biến môi trường và quyền). Trả lý do nếu không nối được.",
    "connect.grant":"Khi phép nối kèm cấp quyền IAM hoặc mở security group: true để làm luôn (mặc định true)",
    set_property:"Đổi một thuộc tính của khối (đường dẫn theo Properties, ví dụ MemorySize hoặc PublicAccessBlockConfiguration.BlockPublicAcls). Đường dẫn bắt đầu bằng @ là Metadata.CloudLab (ví dụ @WorkMs).",
    export_iac:"Xuất sơ đồ hiện tại ra code hạ tầng: cfn (CloudFormation có metadata CloudLab), aws (CloudFormation sạch để deploy), tf (Terraform), cdk (AWS CDK TypeScript)."},
  guide:()=>({format:"CloudFormation YAML; tham chiếu bằng !Ref/!GetAtt/!Sub; phần chỉ cho mô phỏng nằm trong Metadata.CloudLab; vùng ap-southeast-2; không mô phỏng route table, NAT",
    awsTypes:Object.keys(T).filter(t=>!t.startsWith("CloudLab::")),external:Object.fromEntries(Object.values(T).filter(t=>t.type.startsWith("CloudLab::")).map(t=>[t.type,t.fields.map(f=>f.k)])),
    resourceMetadata:Object.fromEntries(Object.values(T).map(t=>[t.type,(t.fields||[]).map(f=>f.k).filter(k=>k&&k.startsWith("@")&&!k.startsWith("@@")).map(k=>k.slice(1))]).filter(x=>x[1].length)),
    guide:"https://dat-2k2.github.io/cloudlab/learn.html#gemini"}),
  setProp:(raw,path,value)=>{if(!path.startsWith("@"))return false;setP(raw,"Metadata.CloudLab."+path.slice(1),value);return true}};
